import{_ as a}from"./chunks/738d0579756a290c0d82f05c51362540.B2f9ghGC.js";import{_ as n}from"./chunks/3221738a8c152b28cb94c27ff9bed5c8.BThW3bQ_.js";import{_ as e,c as i,a2 as o,o as t}from"./chunks/framework.Bzjhwp8w.js";const m=JSON.parse('{"title":"Playground","description":"Playground","frontmatter":{"title":"Playground","description":"Playground","layout":"doc"},"headers":[],"relativePath":"langflow/concepts-playground.md","filePath":"langflow/concepts-playground.md"}'),l={name:"langflow/concepts-playground.md"};function r(p,s,d,c,h,u){return t(),i("div",null,s[0]||(s[0]=[o('<h1 id="playground" tabindex="-1">Playground <a class="header-anchor" href="#playground" aria-label="Permalink to &quot;Playground&quot;">​</a></h1><p><strong>Playground</strong> 是一个为实时与 LLMs（大语言模型）交互而设计的动态界面，允许用户进行聊天，访问记忆，并监控输入和输出。在这里，用户可以直接对他们的模型进行原型设计，进行调整并观察不同的结果。</p><p>只要您有一个 <a href="/dllm/components-io.html">输入或输出</a> 组件在工作，您可以通过点击 <strong>Playground</strong> 按钮来打开它。Playground 的窗口布局会根据使用的组件进行变化。</p><p><img src="'+a+'" alt=""></p><h2 id="在-playground-中运行流程" tabindex="-1">在 Playground 中运行流程 <a class="header-anchor" href="#在-playground-中运行流程" aria-label="Permalink to &quot;在 Playground 中运行流程&quot;">​</a></h2><p>当你在 <strong>Playground</strong> 中运行一个流程时，Langflow 会调用 <code>/build/{flow_id}/flow</code> 端点，该端点位于 <a href="https://github.com/langflow-ai/langflow/blob/main/src/backend/base/langflow/api/v1/chat.py#L162" target="_blank" rel="noreferrer">chat.py</a>。此调用会检索流程数据，构建一个图形，并执行该图形。当每个组件（或节点）被执行时，<code>build_vertex</code> 函数会调用 <code>build_and_run</code>，如果存在，它可能会调用各个组件的 <code>def_build</code> 方法。如果组件没有 <code>def_build</code> 函数，构建仍然会返回一个组件。</p><p><code>build</code> 函数允许组件在运行时执行逻辑。例如，<a href="https://github.com/langflow-ai/langflow/blob/main/src/backend/base/langflow/components/langchain_utilities/recursive_character.py" target="_blank" rel="noreferrer">递归字符文本拆分器</a> 是 <code>LCTextSplitterComponent</code> 类的子类。当需要处理文本时，会调用父类的 <code>build</code> 方法，该方法创建一个 <code>RecursiveCharacterTextSplitter</code> 对象，并根据定义的参数使用其拆分文本。拆分后的文本然后传递给下一个组件。这一切都发生在组件构建时。</p><h2 id="查看-playground-消息通过会话-id" tabindex="-1">查看 Playground 消息通过会话 ID <a class="header-anchor" href="#查看-playground-消息通过会话-id" aria-label="Permalink to &quot;查看 Playground 消息通过会话 ID&quot;">​</a></h2><p>当您从 <strong>Playground</strong> 界面发送消息时，互动会按 <code>session_id</code> 存储在 <strong>消息日志</strong> 中。一个流程可以有多个聊天，不同的流程可以共享同一个聊天。每个聊天将有不同的 <code>session_id</code>。</p><p>要在 Playground 中通过 <code>session_id</code> 查看消息，点击任意聊天会话的 <img src="" alt="Horizontal ellipsis"> 菜单，然后选择 <strong>消息日志</strong>。</p><p><img src="'+n+`" alt=""></p><p>个别消息可以在聊天记忆中进行编辑或删除。修改这些记忆会影响聊天机器人的响应行为。</p><p>要了解有关Langflow中聊天记忆的更多信息，请参阅<a href="/dllm/components-memories.html">记忆组件</a>。</p><h2 id="使用自定义会话-id-来进行多用户交互" tabindex="-1">使用自定义会话 ID 来进行多用户交互 <a class="header-anchor" href="#使用自定义会话-id-来进行多用户交互" aria-label="Permalink to &quot;使用自定义会话 ID 来进行多用户交互&quot;">​</a></h2><p><code>session_id</code> 值用于在流程中追踪用户的交互。默认情况下，如果 <code>session_id</code> 值为空，它将设置为与 <code>flow_id</code> 相同的值。在这种情况下，每次聊天调用使用相同的 <code>session_id</code>，实际上只有一个聊天会话。</p><p><code>session_id</code> 值可以在 <strong>Chat Input</strong> 和 <strong>Chat Output</strong> 组件的<strong>高级设置</strong>中配置。</p><p>要在单个流程中有多个会话，可以在 URL 中用 <code>session_id</code> 参数传递一个特定的会话 ID 给流程。流程中的所有组件将自动使用这个 <code>session_id</code> 值。</p><p>要使用 curl 将消息发送到具有特定会话 ID 的流程，请输入以下命令：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://127.0.0.1:7860/api/v1/run/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$FLOW_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;session_id&quot;: &quot;custom_session_123&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;input_value&quot;: &quot;message&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;input_type&quot;: &quot;chat&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;output_type&quot;: &quot;chat&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   }&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>检查你的流程的<strong>Playground</strong>。除了存储为默认会话的消息外，还将用您的自定义会话 ID 启动一个新会话。</p>`,20)]))}const b=e(l,[["render",r]]);export{m as __pageData,b as default};
